<span class="line"><span style="color:#68747D;">  &quot;</span><span style="color:#101820;">apples</span><span style="color:#68747D;">&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> &quot;There is one apple|There are many apples&quot;</span></span>
